x = Symbol('x')

def nolim_at(N, D, a):
    """N/D 의 x->a 극한이 (유한값으로) 존재하지 않으면 True"""
    Np, Dp = Poly(expand(N), x), Poly(expand(D), x)
    if Dp.is_zero:
        return True
    G = gcd(Np, Dp)
    D1 = quo(Dp, G)
    return D1.eval(a) == 0

def all_ok(N, D):
    """모든 실수 a 에서 극한이 존재하면 True"""
    Np, Dp = Poly(expand(N), x), Poly(expand(D), x)
    G = gcd(Np, Dp)
    D1 = quo(Dp, G)
    return D1.count_roots() == 0

def vals():
    out = set()
    for c in [Rational(k, 2) for k in range(-40, 41)]:
        f = lambda t: (t - 4)*(t - 6)*(t - c)
        expr = cancel(f(x + 2)*(f(x) + 2)/f(x))
        L = limit(expr, x, 4)
        if L == 2:
            out.add(cancel(f(9)*(f(7) + 2)/f(7)))
    return out

def skill():
    c = 5
    f = lambda t: (t - 4)*(t - 6)*(t - c)
    assert 2*diff(f(x), x).subs(x, 6) == 2*diff(f(x), x).subs(x, 4)
    return f(9)*(f(7) + 2)/f(7)

def standard():
    v = vals()
    assert len(v) == 1
    return list(v)[0]

def unique():
    return sorted(vals())
